import{_ as e,o as i,c as t,a5 as o}from"./chunks/framework.CX7j2CRp.js";const m=JSON.parse('{"title":"AI 每日简报：2026-08-01","description":"记录过去24小时 AI 产品与开发工具的重要变化及其迁移影响。","frontmatter":{"title":"AI 每日简报：2026-08-01","category":"每日记录","tags":["AI","GitHub Copilot","Gemini"],"date":"2026-08-01T00:00:00.000Z","description":"记录过去24小时 AI 产品与开发工具的重要变化及其迁移影响。","wordCount":433},"headers":[],"relativePath":"posts/daily/20260801-ai-daily.md","filePath":"posts/daily/20260801-ai-daily.md","lastUpdated":1785846707000}'),l={name:"posts/daily/20260801-ai-daily.md"};function r(n,a,h,s,p,c){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="ai-每日简报-2026-08-01" tabindex="-1">AI 每日简报：2026-08-01 <a class="header-anchor" href="#ai-每日简报-2026-08-01" aria-label="Permalink to &quot;AI 每日简报：2026-08-01&quot;">​</a></h1><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><p>过去24小时未发现 OpenAI、Anthropic 或 Google 发布重大新模型或核心产品功能。</p><p>GitHub Copilot 于 2026-07-31 停用 Gemini 2.5 Pro 与 Gemini 3 Flash。该事项在 2026-07-02 提前公告，实际停用发生在本统计窗口内。</p><h2 id="产品与模型" tabindex="-1">产品与模型 <a class="header-anchor" href="#产品与模型" aria-label="Permalink to &quot;产品与模型&quot;">​</a></h2><h3 id="github-copilot-模型停用" tabindex="-1">GitHub Copilot 模型停用 <a class="header-anchor" href="#github-copilot-模型停用" aria-label="Permalink to &quot;GitHub Copilot 模型停用&quot;">​</a></h3><ul><li>具体变化：Gemini 2.5 Pro 与 Gemini 3 Flash 已从 GitHub Copilot 中停用。</li><li>适用场景：固定选择旧模型、使用企业模型策略或 Agent Mode 的团队。</li><li>可能影响：旧配置失效或回退，替代模型未启用时可能不可用，Agent 行为与评测基线需要重新验证。</li><li>是否值得立即尝试：值得立即处理迁移与回归测试。</li><li>替代建议：Gemini 2.5 Pro 迁移至 Gemini 3.1 Pro；Gemini 3 Flash 迁移至 Gemini 3.5 Flash。</li></ul><h3 id="openai-与-anthropic" tabindex="-1">OpenAI 与 Anthropic <a class="header-anchor" href="#openai-与-anthropic" aria-label="Permalink to &quot;OpenAI 与 Anthropic&quot;">​</a></h3><p>统计窗口内没有发现需要立即迁移或测试的实质更新。</p><h2 id="agent-skill-mcp-开发工具" tabindex="-1">Agent / Skill / MCP / 开发工具 <a class="header-anchor" href="#agent-skill-mcp-开发工具" aria-label="Permalink to &quot;Agent / Skill / MCP / 开发工具&quot;">​</a></h2><p>统计窗口内未发现重大 Skill、Agent 或 MCP 官方发布。建议检查 Copilot 的模型策略、IDE 模型选择和 Agent 自动化配置，避免硬编码已停用的模型名称。</p><h2 id="值得关注的趋势" tabindex="-1">值得关注的趋势 <a class="header-anchor" href="#值得关注的趋势" aria-label="Permalink to &quot;值得关注的趋势&quot;">​</a></h2><p>模型退役已经从聊天界面的产品变化，演变为影响 Agent 规划、工具调用、自动化任务和企业治理的依赖升级事件。团队应集中管理模型映射，并维护替代模型与回归测试基线。</p><h2 id="原始来源" tabindex="-1">原始来源 <a class="header-anchor" href="#原始来源" aria-label="Permalink to &quot;原始来源&quot;">​</a></h2><ul><li>GitHub Changelog：<a href="https://github.blog/changelog/2026-07-02-upcoming-deprecation-of-gemini-2-5-pro-and-gemini-3-flash/" target="_blank" rel="noreferrer">https://github.blog/changelog/2026-07-02-upcoming-deprecation-of-gemini-2-5-pro-and-gemini-3-flash/</a></li><li>OpenAI Release Notes：<a href="https://openai.com/products/release-notes/" target="_blank" rel="noreferrer">https://openai.com/products/release-notes/</a></li><li>OpenAI News：<a href="https://openai.com/news/" target="_blank" rel="noreferrer">https://openai.com/news/</a></li><li>Anthropic Newsroom：<a href="https://www.anthropic.com/news" target="_blank" rel="noreferrer">https://www.anthropic.com/news</a></li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>统计窗口为 2026-07-31 08:30 至 2026-08-01 08:30（Asia/Shanghai）。未使用窗口外旧闻填充。</p>',17)])])}const u=e(l,[["render",r]]);export{m as __pageData,u as default};
